const D = { density:.55, energy:.5, wind:.2, speed:1, hue:205, scale:1, y:.97, x:.5, style:'soft', seed:0, act:'calm' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const isSoft=st==='soft', isCrystal=st==='crystal', isHalf=st==='halftone', isRiso=st==='riso';
const act=P.act||'calm';

let envD=1, envW=1;
if(act==='gust'){ envW=1.7; }
else if(act==='blizzard'){ envD=1.35; envW=2.3; }
const arc=0.5+0.6*K.intensity;
const dens=clp(P.density*envD,0,1.4);
const en=clp(P.energy*arc,0,1.3);
const gust=(P.wind + 0.4*Math.sin(K.t*0.17) + 0.15*Math.sin(K.t*0.6))*envW + A.bass*0.55;

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// pre-blurred soft glow sprites, pre-tinted per depth bucket (built once per hue).
// tint() forces p5 to rebuild a tinted copy of the sprite on a fresh offscreen
// canvas on EVERY image() call — at 260 flakes/frame that alone halves the fps.
const NB=8, HQ=Math.round(H/30)*30;
const SC=window.state.__snowSpr||(window.state.__snowSpr={});
let sprites=SC[HQ];
if(!sprites){
  sprites=[];
  for(let b=0;b<NB;b++){ const dp=(b+0.5)/NB, sat=lrp(6,16,dp);
    const g=createGraphics(48,48); g.colorMode(HSB,360,100,100,100); g.noStroke();
    for(let r=24;r>0;r--){ const t=r/24; g.fill(HQ,sat,100,14*(1-t)*(1-t)); g.ellipse(24,24,r*2,r*2); }
    sprites.push(g); }
  SC[HQ]=sprites;
  const ks=Object.keys(SC);
  if(ks.length>8){ SC[ks[0]].forEach(g=>g.remove()); delete SC[ks[0]]; }
}

let nF=Math.round(lrp(60,260,dens));
if(isCrystal) nF=Math.round(nF*0.6);
imageMode(CENTER);

for(let i=0;i<nF;i++){
  const depth=fr(i*2+2);
  const fallSp=lrp(0.16,0.5,depth)*P.speed;
  const life=frc(fr(i*2+1)+K.t*fallSp*0.42);
  const sway=Math.sin(K.t*(0.5+depth*0.9)+fr(i*2+5)*6.2832)*u*0.045*(0.5+depth);
  const baseX=fr(i*2+3);
  let x=baseX*W + sway + gust*u*0.34*life;
  x=md(x,W+u*0.1)-u*0.05;
  const y=-0.05*Hh + life*(P.y*Hh+0.12*Hh);
  const sz=u*0.0065*P.scale*(0.4+en)*lrp(0.45,1.7,depth);
  const al=lrp(28,95,depth);
  if(isSoft){
    blendMode(BLEND); noStroke();
    drawingContext.globalAlpha=al/100;
    image(sprites[Math.min(NB-1,Math.floor(depth*NB))],x,y,sz*7,sz*7);
    drawingContext.globalAlpha=1;
  } else if(isCrystal){
    push(); translate(x,y); rotate(K.t*0.3*(depth>0.5?1:-1)+fr(i*2+7)*6.28);
    stroke(md(H,360),lrp(8,20,depth),100,al); strokeWeight(Math.max(0.5,sz*0.5)); noFill();
    for(let a2=0;a2<6;a2++){ const an=a2*Math.PI/3;
      line(0,0,Math.cos(an)*sz*2.6,Math.sin(an)*sz*2.6);
      const bx=Math.cos(an)*sz*1.6, by=Math.sin(an)*sz*1.6;
      line(bx,by,bx+Math.cos(an+0.9)*sz*0.9,by+Math.sin(an+0.9)*sz*0.9);
      line(bx,by,bx+Math.cos(an-0.9)*sz*0.9,by+Math.sin(an-0.9)*sz*0.9); }
    pop();
  } else if(isHalf){
    noStroke(); const q=Math.round(lrp(1,3,frc(fr(i*2+9))));
    fill(md(H,360),lrp(4,12,depth),100,al); ellipse(x,y,sz*q*1.8,sz*q*1.8);
    fill(240,30,12,al*0.5); ellipse(x,y,sz*q*0.7,sz*q*0.7);
  } else { // riso two-ink misregistration
    noStroke();
    blendMode(MULTIPLY);
    fill(190,55,100,al*0.7); ellipse(x-sz*0.6,y,sz*2.4,sz*2.4);
    fill(330,45,100,al*0.7); ellipse(x+sz*0.6,y+sz*0.3,sz*2.4,sz*2.4);
    blendMode(BLEND);
  }
}
noTint(); blendMode(BLEND);

// ---- settled snow band with wavy top edge + faint shimmer ----
const setY=P.y*Hh+u*0.01;
noStroke(); fill(md(H,360),8,lrp(78,90,0.5+0.5*Math.sin(K.t*0.8)),34);
beginShape(); vertex(0,Hh);
for(let sx=0;sx<=W;sx+=W/22){ const wv=Math.sin(sx*0.02+K.t*0.4+fr(Math.round(sx))*2)*u*0.012+Math.sin(sx*0.008-K.t*0.2)*u*0.02; vertex(sx,setY+wv); }
vertex(W,Hh); endShape(CLOSE);

drawingContext.shadowBlur=0;
